import re

def calc(expr):
    tokens = re.findall(r'\d+|[+\-*/()]', expr)
    pos = [0]

    def peek():
        return tokens[pos[0]] if pos[0] < len(tokens) else None

    def advance():
        tok = tokens[pos[0]]
        pos[0] += 1
        return tok

    def parse_expr():
        val = parse_term()
        while peek() in ('+', '-'):
            op = advance()
            rhs = parse_term()
            if op == '+':
                val += rhs
            else:
                val -= rhs
        return val

    def parse_term():
        val = parse_factor()
        while peek() in ('*', '/'):
            op = advance()
            rhs = parse_factor()
            if op == '*':
                val *= rhs
            else:
                # truncate toward zero
                sign = -1 if (val < 0) != (rhs < 0) else 1
                val = sign * (abs(val) // abs(rhs))
        return val

    def parse_factor():
        neg = False
        while peek() == '-':
            advance()
            neg = not neg
        val = parse_primary()
        if neg:
            val = -val
        return val

    def parse_primary():
        tok = peek()
        if tok == '(':
            advance()
            val = parse_expr()
            advance()  # consume ')'
            return val
        else:
            advance()
            return int(tok)

    result = parse_expr()
    return result

